using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Cryptography;
using System.Text;
using System.Threading.Tasks;

// Base classes for all blockchain components
public abstract class BlockchainModule
{
    protected readonly SHA256 sha256 = SHA256.Create();
    protected const int Difficulty = 4; // Adjust for mining difficulty
}

public class Transaction
{
    public string TransactionId { get; }
    public string FromAddress { get; }
    public string ToAddress { get; }
    public decimal Amount { get; }
    public string Signature { get; }
    public DateTime Timestamp { get; }
    public List<string> Inputs { get; } = new List<string>();
    public List<string> Outputs { get; } = new List<string>();

    public Transaction(string fromAddress, string toAddress, decimal amount, string signature)
    {
        FromAddress = fromAddress;
        ToAddress = toAddress;
        Amount = amount;
        Signature = signature;
        TransactionId = ComputeTransactionHash();
        Timestamp = DateTime.UtcNow;
    }

    public string ComputeTransactionHash()
    {
        using var sha256 = SHA256.Create();
        var input = Encoding.UTF8.GetBytes($"{FromAddress}{ToAddress}{Amount}{Timestamp}");
        return BitConverter.ToString(sha256.ComputeHash(input)).Replace("-", "").ToLower();
    }

    public bool VerifySignature(string publicKey)
    {
        // In a real implementation, this would use proper cryptographic verification
        // This is a simplified placeholder
        return Signature == $"{publicKey}_{TransactionId}";
    }
}

public class Block
{
    public string Hash { get; set; }
    public string PreviousHash { get; set; }
    public List<Transaction> Transactions { get; } = new List<Transaction>();
    public int Nonce { get; set; }
    public DateTime Timestamp { get; }

    public Block(string previousHash)
    {
        PreviousHash = previousHash;
        Timestamp = DateTime.UtcNow;
    }

    public void AddTransaction(Transaction transaction)
    {
        Transactions.Add(transaction);
    }

    public string ComputeHash()
    {
        using var sha256 = SHA256.Create();
        var input = Encoding.UTF8.GetBytes($"{PreviousHash}{Nonce}{string.Join("", Transactions.Select(t => t.TransactionId))}");
        return BitConverter.ToString(sha256.ComputeHash(input)).Replace("-", "").ToLower();
    }

    public bool IsValid()
    {
        Hash = ComputeHash();
        var hashMatches = Hash.StartsWith(new string('0', Difficulty));
        return hashMatches;
    }
}

// 1. Transaction Pool Module
public class TransactionPool : BlockchainModule
{
    private readonly Dictionary<string, Transaction> _transactions = new Dictionary<string, Transaction>();
    private readonly Dictionary<string, decimal> _unspentOutputs = new Dictionary<string, decimal>();
    private readonly Dictionary<string, decimal> _balances = new Dictionary<string, decimal>();

    public void AddTransaction(Transaction transaction)
    {
        if (transaction == null || transaction.TransactionId == null)
            throw new ArgumentException("Invalid transaction");

        if (!_unspentOutputs.ContainsKey(transaction.FromAddress))
        {
            throw new InvalidOperationException("Insufficient funds");
        }

        if (_unspentOutputs[transaction.FromAddress] < transaction.Amount)
        {
            throw new InvalidOperationException("Insufficient funds");
        }

        if (!_transactions.ContainsKey(transaction.TransactionId))
        {
            _transactions.Add(transaction.TransactionId, transaction);
            _unspentOutputs[transaction.ToAddress] = _unspentOutputs.GetValueOrDefault(transaction.ToAddress, 0) + transaction.Amount;
            _unspentOutputs[transaction.FromAddress] -= transaction.Amount;

            // Update balances
            _balances[transaction.FromAddress] = _balances.GetValueOrDefault(transaction.FromAddress, 0) - transaction.Amount;
            _balances[transaction.ToAddress] = _balances.GetValueOrDefault(transaction.ToAddress, 0) + transaction.Amount;
        }
    }

    public List<Transaction> GetPendingTransactions()
    {
        return _transactions.Values.ToList();
    }

    public bool VerifyTransaction(Transaction transaction)
    {
        if (!transaction.VerifySignature(transaction.FromAddress))
            return false;

        if (!_unspentOutputs.ContainsKey(transaction.FromAddress) ||
            _unspentOutputs[transaction.FromAddress] < transaction.Amount)
            return false;

        return true;
    }

    public void Reset()
    {
        _transactions.Clear();
        _unspentOutputs.Clear();
        _balances.Clear();
    }
}

// 2. Block Miner Module
public class BlockMiner : BlockchainModule
{
    private readonly TransactionPool _transactionPool;
    private readonly ChainValidator _chainValidator;

    public BlockMiner(TransactionPool transactionPool, ChainValidator chainValidator)
    {
        _transactionPool = transactionPool;
        _chainValidator = chainValidator;
    }

    public Block MineBlock()
    {
        var pendingTransactions = _transactionPool.GetPendingTransactions();
        if (pendingTransactions.Count == 0)
        {
            // Create a coinbase transaction (miner reward)
            var coinbaseTx = new Transaction("0", "miner", 1.0m, "miner_reward");
            pendingTransactions.Add(coinbaseTx);
        }

        var lastBlockHash = _chainValidator.GetLastBlockHash();
        var newBlock = new Block(lastBlockHash);

        foreach (var tx in pendingTransactions)
        {
            if (_transactionPool.VerifyTransaction(tx))
            {
                newBlock.AddTransaction(tx);
            }
        }

        // Mine the block
        while (!newBlock.IsValid())
        {
            newBlock.Nonce++;
        }

        // Clear the transaction pool after mining
        _transactionPool.Reset();

        return newBlock;
    }
}

// 3. Chain Validator Module
public class ChainValidator : BlockchainModule
{
    private readonly List<Block> _blockchain = new List<Block>();
    private readonly TransactionPool _transactionPool;

    public ChainValidator(TransactionPool transactionPool)
    {
        _transactionPool = transactionPool;
        // Initialize with genesis block
        var genesisBlock = new Block("0");
        genesisBlock.Hash = genesisBlock.ComputeHash();
        _blockchain.Add(genesisBlock);
    }

    public void AddBlock(Block newBlock)
    {
        if (!IsValidBlock(newBlock))
            throw new InvalidOperationException("Invalid block");

        _blockchain.Add(newBlock);
    }

    public bool IsValidBlock(Block block)
    {
        if (block == null || block.Transactions == null)
            return false;

        if (block.PreviousHash != GetLastBlockHash())
            return false;

        if (!block.IsValid())
            return false;

        // Verify all transactions in the block
        foreach (var tx in block.Transactions)
        {
            if (!_transactionPool.VerifyTransaction(tx))
                return false;
        }

        return true;
    }

    public string GetLastBlockHash()
    {
        return _blockchain.Last().Hash;
    }

    public List<Block> GetBlockchain()
    {
        return _blockchain;
    }

    public bool IsChainValid()
    {
        for (int i = 1; i < _blockchain.Count; i++)
        {
            var currentBlock = _blockchain[i];
            var previousBlock = _blockchain[i - 1];

            if (currentBlock.Hash != currentBlock.ComputeHash())
                return false;

            if (currentBlock.PreviousHash != previousBlock.Hash)
                return false;

            if (!currentBlock.IsValid())
                return false;
        }
        return true;
    }
}

// Enterprise Blockchain Ledger
public class EnterpriseBlockchainLedger
{
    private readonly TransactionPool _transactionPool;
    private readonly BlockMiner _blockMiner;
    private readonly ChainValidator _chainValidator;

    public EnterpriseBlockchainLedger()
    {
        _transactionPool = new TransactionPool();
        _chainValidator = new ChainValidator(_transactionPool);
        _blockMiner = new BlockMiner(_transactionPool, _chainValidator);
    }

    public void AddTransaction(Transaction transaction)
    {
        _transactionPool.AddTransaction(transaction);
    }

    public Block MineNewBlock()
    {
        return _blockMiner.MineBlock();
    }

    public void AddBlockToChain(Block block)
    {
        _chainValidator.AddBlock(block);
    }

    public bool IsChainValid()
    {
        return _chainValidator.IsChainValid();
    }

    public List<Block> GetBlockchain()
    {
        return _chainValidator.GetBlockchain();
    }

    public List<Transaction> GetPendingTransactions()
    {
        return _transactionPool.GetPendingTransactions();
    }
}

// Example usage
class Program
{
    static async Task Main(string[] args)
    {
        var ledger = new EnterpriseBlockchainLedger();

        // Add some transactions
        ledger.AddTransaction(new Transaction("alice", "bob", 1.0m, "alice_bob_1.0"));
        ledger.AddTransaction(new Transaction("bob", "charlie", 0.5m, "bob_charlie_0.5"));

        // Mine a block
        var minedBlock = ledger.MineNewBlock();
        Console.WriteLine($"Mined block with hash: {minedBlock.Hash}");

        // Add the block to the chain
        ledger.AddBlockToChain(minedBlock);

        // Check chain validity
        Console.WriteLine($"Is chain valid? {ledger.IsChainValid()}");

        // Get pending transactions
        var pending = ledger.GetPendingTransactions();
        Console.WriteLine($"Pending transactions: {pending.Count}");
    }
}
